local function decode(v)
 local accumulator,bits=0,0;local bytes={};local count=0
 for i=1,#v do
  local digit=lookup[v:sub(i,i)]
  if digit then
   accumulator=accumulator*64+digit;bits=bits+6
   if bits>=8 then
    bits=bits-8;count=count+1
    bytes[count]=string.char(math.floor(accumulator/2^bits)%256)
    accumulator=accumulator%2^bits
   end
  end
 end
 return table.concat(bytes)
end
local function descramble(raw)
 local parts={};local chunk={};local n=0
 for i=1,#raw do
  n=n+1;chunk[n]=string.char((raw:byte(i)-(i*29+113))%256)
  if n>=2048 then parts[#parts+1]=table.concat(chunk);chunk={};n=0 end
 end
 if n>0 then parts[#parts+1]=table.concat(chunk) end
 return table.concat(parts)
end
local function inflate(raw)
 local out={};local n,i=0,1
 while i<=#raw do
  local bits=raw:byte(i);i=i+1
  for _=1,8 do
   if i>#raw then break end
   if bits%2==1 then
    local a,b,c=raw:byte(i,i+2);i=i+3
    if not c then error('Invalid packed data') end
    local distance=a*256+b
    if distance<1 or distance>n then error('Invalid back-reference') end
    for _=1,c+4 do n=n+1;out[n]=out[n-distance] end
   else
    n=n+1;out[n]=raw:byte(i);i=i+1
   end
   bits=math.floor(bits/2)
  end
 end
 local chunks={}
 for j=1,n,2048 do chunks[#chunks+1]=string.char(table.unpack(out,j,math.min(n,j+2047))) end
 return table.concat(chunks)
end
